# Regenerates src/TrustedInventory.Api/Contract/OperationPolicies.g.cs from docs/openapi.yaml.
# The contract is the single source for x-access, x-entitlement and x-quota (DEC-034, DEC-038);
# ContractConformanceTests fails when the generated file is stale.
# Usage: powershell -NoProfile -ExecutionPolicy Bypass -File scripts/generate-operation-policies.ps1
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$lines = [IO.File]::ReadAllLines((Join-Path $root 'docs/openapi.yaml'))

$ops = [ordered]@{}
$inPaths = $false
$current = $null
foreach ($line in $lines) {
    if ($line -match '^paths:\s*$') { $inPaths = $true; continue }
    if ($inPaths -and $line -match '^\S') { break }
    if (-not $inPaths) { continue }
    if ($line -match '^    (get|post|put|patch|delete):\s*$') { $current = @{ id = $null; access = $null; entitlement = $null; quota = $null }; continue }
    if ($line -match '^  /') { $current = $null; continue }
    if ($null -eq $current) { continue }
    if ($line -match '^      operationId:\s*(\S+)\s*$') { $current.id = $Matches[1]; $ops[$current.id] = $current }
    elseif ($line -match '^      x-access:\s*(\S+)\s*$') { $current.access = $Matches[1] }
    elseif ($line -match '^      x-entitlement:\s*(\S+)\s*$') { $current.entitlement = $Matches[1] }
    elseif ($line -match '^      x-quota:\s*(\S+)\s*$') { $current.quota = $Matches[1] }
}

function Lit($v) { if ($null -eq $v) { 'null' } else { '"' + $v + '"' } }
$entries = foreach ($k in ($ops.Keys | Sort-Object)) {
    $o = $ops[$k]
    if (-not $o.access) { throw "Operation $k has no x-access." }
    '        ["{0}"] = new("{1}", {2}, {3}),' -f $k, $o.access, (Lit $o.entitlement), (Lit $o.quota)
}

$out = @"
// <auto-generated>
// Generated by scripts/generate-operation-policies.ps1 from docs/openapi.yaml. Do not edit by hand.
// </auto-generated>
#nullable enable
namespace TrustedInventory.Api.Contract;

/// <summary>Per-operation SaaS policy from the contract: access category, feature key, quota key.</summary>
public sealed record OperationPolicy(string Access, string? Entitlement, string? Quota);

public static class OperationPolicies
{
    public static readonly IReadOnlyDictionary<string, OperationPolicy> ByOperationId = new Dictionary<string, OperationPolicy>(StringComparer.Ordinal)
    {
$($entries -join "`n")
    };
}
"@
$target = Join-Path $root 'src/TrustedInventory.Api/Contract/OperationPolicies.g.cs'
New-Item -ItemType Directory -Force (Split-Path $target) | Out-Null
[IO.File]::WriteAllText($target, $out.Replace("`r`n", "`n"), (New-Object Text.UTF8Encoding $false))
"wrote $($ops.Count) operations to $target"
